CREATE TABLE IF NOT EXISTS "locations" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"creator_id" INTEGER,
	"name" VARCHAR(255),
	"description" TEXT,
	"lon" DECIMAL CHECK(("lon" IS NULL OR "lon" BETWEEN -180 AND 180)),
	"lat" DECIMAL CHECK(("lat" IS NULL OR "lat" BETWEEN -90 AND 90)),
	"public_at" TIMESTAMPTZ,
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "stages" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"game_id" INTEGER NOT NULL,
	"location_id" INTEGER NOT NULL,
	"qrcode_uid" VARCHAR(255),
	"determine_range" DECIMAL CHECK(("determine_range" IS NULL OR "determine_range" >= 0)),
	"limit_seconds" INTEGER CHECK(("limit_seconds" IS NULL OR "limit_seconds" >= 0)),
	"quest" JSONB,
	"is_end" BOOLEAN NOT NULL DEFAULT FALSE,
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
	PRIMARY KEY("id")
);
CREATE INDEX "stages_index_0"
ON "stages" ("game_id");

CREATE TABLE IF NOT EXISTS "games" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"creator_id" INTEGER NOT NULL,
	"game_code" VARCHAR(255) NOT NULL UNIQUE,
	"start_stage_id" INTEGER,
	"name" VARCHAR(255),
	"description" TEXT,
	"area_geojson" JSONB,
	"setting" JSONB,
	"limit_seconds" INTEGER CHECK(("limit_seconds" IS NULL OR "limit_seconds" >= 0)),
	"is_public" BOOLEAN,
	"publish_at" TIMESTAMPTZ,
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "next_stages" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"game_id" INTEGER NOT NULL,
	"now_stage_id" INTEGER NOT NULL,
	"option_stage_id" INTEGER,
	"sort_id" INTEGER NOT NULL,
	PRIMARY KEY("id"),
	CONSTRAINT "nextStages_unique_0" UNIQUE ("game_id", "now_stage_id", "sort_id")
);
CREATE INDEX "nextStages_index_0"
ON "next_stages" ("game_id");
CREATE INDEX "nextStages_index_1"
ON "next_stages" ("now_stage_id");


